// Notion APIレスポンスからデータ抽出してスコアリング
const notionResponse = $input.first().json;
const articles = notionResponse.results || [];

const scoredArticles = articles.map(page => {
  const props = page.properties;

  const title = props.Title?.title[0]?.text?.content || '';
  const url = props.URL?.url || '';
  const articleId = props['Article ID']?.rich_text[0]?.text?.content || '';
  const viewCount = props['View Count']?.number || 0;
  const likeCount = props['Like Count']?.number || 0;
  const description = props.Description?.rich_text[0]?.text?.content || '';
  const categories = props.Category?.multi_select?.map(c => c.name) || [];
  const publishedDate = props['Published Date']?.date?.start || '';

  const score = (viewCount * 0.6) + (likeCount * 0.4);

  return {
    pageId: page.id,
    title,
    url,
    articleId,
    viewCount,
    likeCount,
    score,
    description,
    categories,
    publishedDate
  };
});

scoredArticles.sort((a, b) => b.score - a.score);

return scoredArticles.map(article => ({ json: article }));

const articles = $input.all().map(item => item.json);
const top10 = articles.slice(0, 10);
return [{ json: { articles: top10 } }];

const articles = $input.first().json.articles;

const prompt = `以下の人気note記事データから、トレンドトピックを抽出してください。

【データ】
${JSON.stringify(articles, null, 2)}

【分析観点】
1. 共通キーワードの抽出（5-10個）
2. ユーザーニーズの推定（保護者の悩み・関心）
3. 次に書くべきトピック提案（5つ、優先度順）

【ターゲット】
3-10歳の子供を持つ保護者、英語教育・バイリンガル教育に関心

【出力形式】
必ずJSON形式のみで出力してください。それ以外のテキストは含めないでください。
{
  "trendKeywords": ["キーワード1", "キーワード2", ...],
  "userNeeds": "ニーズ分析テキスト",
  "nextTopics": [
    {"topic": "トピック名", "priority": 1, "reason": "理由"},
    ...
  ]
}`;

return [{
  json: {
    model: "gpt-4-turbo-preview",
    messages: [
      {
        role: "system",
        content: "あなたはコンテンツストラテジストです。note記事データから、トレンドトピックを抽出してください。"
      },
      {
        role: "user",
        content: prompt
      }
    ],
    temperature: 0.7,
    max_tokens: 1500
  }
}];

const gptResponse = $input.first().json;
let content = gptResponse.choices[0].message.content;

// マークダウンコードブロックを除去
content = content.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

let analysis;
try {
  analysis = JSON.parse(content);
} catch (e) {
  throw new Error(`GPT-4レスポンスのJSON parse失敗: ${content}`);
}

return [{ json: analysis }];

const analysis = $input.first().json;
const top10Articles = $('Function - トップ10記事抽出').first().json.articles;

const topics = analysis.nextTopics.map(topic => {
  const relatedArticles = top10Articles.filter(article => {
    const matchKeyword = analysis.trendKeywords.some(keyword =>
      article.title.includes(keyword) ||
      article.description.includes(keyword) ||
      article.categories.includes(keyword)
    );
    return matchKeyword;
  });

  const relatedArticleIds = relatedArticles.map(a => a.pageId);

  const avgScore = relatedArticles.length > 0
    ? relatedArticles.reduce((sum, a) => sum + a.score, 0) / relatedArticles.length
    : 0;

  return {
    topic: topic.topic,
    priority: topic.priority,
    reason: topic.reason,
    trendKeywords: analysis.trendKeywords,
    relatedArticleIds,
    avgScore
  };
});

return topics.map(t => ({ json: t }));

