const topics = $('Function - トピックデータ前処理').all();
const trendKeywords = $('Function - GPT-4レスポンスパース').first().json.trendKeywords;

const topicsText = topics.map((t, i) => {
  return `${i+1}. *${t.json.topic}*\nスコア: ${t.json.avgScore.toFixed(1)} | 関連記事: ${t.json.relatedArticleIds.length}件\n理由: ${t.json.reason}`;
}).join('\n\n');

return [{
  json: {
    text: "📊 *今週のトレンドトピック分析完了*",
    blocks: [
      {
        type: "header",
        text: {
          type: "plain_text",
          text: "🔥 トレンドトピック Top 5"
        }
      },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: topicsText
        }
      },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: `*トレンドキーワード*: ${trendKeywords.join(', ')}`
        }
      }
    ]
  }
}];
